2. 다음은 같은 기능을 수행하는 두 함수를 구현한 C 코드이다. 각 함수의
시간 복잡도를 바르게 연결한 것은?
double p1(double x, int n) {
int i;
double result = 1.0;
for(i = 0; i < n; i++)
result = result * x;
return result;
}
double p2(double x, int n) {
if(n == 0)
return 1;
else if((n % 2) == 0)
return p2(x * x, n/2);
else
return x * p2(x * x, (n - 1)/2);
}
