O()
②O()
O(log)
③O()
O()
④O(log)
O(log)

3. 다음은 이중 연결 리스트(doubly linked list)를 구현한 C 코드이다.
노드 삭제 함수의 빈칸에 들어갈 내용으로 옳은 것은?
typedef int element;
typedef struct DListNode {
element data;
struct DListNode *llink;
struct DListNode *rlink;
} DListNode;
DListNode *head = NULL;
void init() {
head = (DListNode*)malloc(sizeof(DListNode));
head->llink = head->rlink = head;
}
void dinsert(DListNode *inode, DListNode *inserted) {
inserted->llink = inode;
inserted->rlink = inode->rlink;
inode->rlink->llink = inserted;
inode->rlink = inserted;
}
void ddelete(DListNode *removed) {
if(removed == head) return;
removed->llink->rlink = removed->rlink;
free(removed);
}
