24. 다음 C 프로그램의 실행 결과는?
#include <stdio.h>
int count = 0;
void new_hanoi(int n, char from, char tmp, char to) {
if (n <= 2)
count += n;
else {
new_hanoi(n - 2, from, to, tmp);
count += 2;
new_hanoi(n - 2, tmp, from, to);
}
}
int main() {
new_hanoi(9, 'A', 'B', 'C');
printf("%d", count);
return 0;
}
①31
②46
③62
④511

